import{_ as l,o as i,c as o,a2 as a}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Сборка проекта","description":"","frontmatter":{"pageId":"developers/build","contentRevision":5},"headers":[],"relativePath":"ru/developers/build.md","filePath":"ru/developers/build.md"}'),t={name:"ru/developers/build.md"};function r(s,e,n,d,u,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="сборка-проекта" tabindex="-1">Сборка проекта <a class="header-anchor" href="#сборка-проекта" aria-label="Permalink to &quot;Сборка проекта&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Используйте SDK 10.0.403, выбранный global.json с rollForward=disable. Собирайте в изолированном каталоге toolchain и фиксируйте загруженный runtime вместе с SDK. Runtimeconfig сервера и CLI требует NETCore и ASP.NET 10.0.14 с RollForward=Disable. Мод использует runtime установленной игры; пересобирайте его и dev-компаньон при обновлении RimWorld.</p><p>Установи SDK из global.json; версии пакетов централизованы в Directory.Packages.props. Из корня выполни:</p><p><code>dotnet build Rimlink.sln</code></p><p><code>dotnet test Rimlink.sln -nologo -v q</code></p><p>Мод не включён в solution: закрой игру и используй PowerShell scripts/Build-ClientMod.ps1 -RimWorldDir &lt;game&gt; -InstallTo &lt;game/Mods&gt;. -BundleHarmony допустим лишь для локального запуска без отдельного Harmony, не релиза. scripts/Package-Release.ps1 собирает release ZIP.</p><p>Для wiki: npm --prefix wiki ci --ignore-scripts, затем run test:checks, check:content, check:reference, build, check:links. Node 24 закреплён отдельно. Для BridgeTools нужен отдельный Build-BridgeTools.ps1 и установленная игра.</p><h2 id="build-track" tabindex="-1">От чистого checkout до сборки мода <a class="header-anchor" href="#build-track" aria-label="Permalink to &quot;От чистого checkout до сборки мода {#build-track}&quot;">​</a></h2><ol><li>Прочти global.json и установи подходящий SDK; проверь dotnet --info. Не обновляй центральные зависимости ради обхода локальной ошибки.</li><li>Из корня выполни dotnet build Rimlink.sln, затем dotnet test Rimlink.sln -nologo -v q. Это собирает server/core/tools/tests, не игровой мод.</li><li>Для мода нужен установленный RimWorld 1.7 с Assembly-CSharp.dll и PowerShell. Закрой принадлежащую тебе тестовую игру, укажи -RimWorldDir и <strong>новый -OutputDir</strong> в Build-ClientMod.ps1. Без -InstallTo скрипт только собирает папку; не трогай чужой live Mods.</li><li>Проверь About, Languages и Assemblies результата. Harmony не включай в релиз; -BundleHarmony — только локальный вариант.</li><li>Установка в тестовую копию и запуск двух клиентов — следующий отдельный этап приёмки, не следствие успешной компиляции.</li></ol><p>Скрипт очищает выбранный OutputDir, поэтому не направляй его на каталог исходников, игру или единственную копию данных.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не заменяй DLL работающей игры и не перезапускай чужой экземпляр. Успешный solution build не доказывает сборку мода и игру. Не коммить bin/obj/data/сейвы/секреты и generated wiki output.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./testing">Тестирование и приёмка</a></li><li><a href="./contributing">Вклад и сопровождение wiki</a></li><li><a href="./../admins/hosting">Размещение и запуск</a></li></ul>',16)])])}const m=l(t,[["render",r]]);export{h as __pageData,m as default};
